// Parse large JSON payloads for base64 image/PDF uploads
app.use(express.json({ limit: '50mb' }));

// Helper to get Gemini Client
function getGeminiClient() {
  const apiKey = process.env.GEMINI_API_KEY || process.env.VITE_GEMINI_API_KEY;
  if (!apiKey) {
    return null;
  }
  return new GoogleGenAI({
    apiKey,
    httpOptions: {
      headers: {
        'User-Agent': 'aistudio-build',
      },
    },
  });
}

// Helper to call Gemini with automatic model fallback to avoid 429 quota exhaustion errors.
async function generateContentWithFallback(ai: any, params: any) {
  const modelsToTry = [
    params.model || 'gemini-3.6-flash',
    'gemini-3.5-flash-lite',
    'gemini-3.7-flash',
    'gemini-flash-latest'
  ];

  let lastError = null;
  for (const modelName of modelsToTry) {
    try {
      console.log(`Trying Gemini generation with model: ${modelName}`);
      const response = await ai.models.generateContent({
        ...params,
        model: modelName,
      });
      return response;
    } catch (err: any) {
      console.warn(`Gemini generation failed for model ${modelName}:`, err.message || err);
      lastError = err;
    }
  }
  throw lastError;
}

// Helper to prepare contents supporting images, PDFs, and Word .docx documents via mammoth
async function prepareContents(systemPrompt: string, imageBase64?: string, mimeType?: string, textContent?: string) {
  if (textContent) {
    return [systemPrompt, `Berikut adalah teks dokumen:\n\n${textContent}`];
  }
  if (imageBase64) {
    const cleanBase64 = imageBase64.replace(/^data:[^;]+;base64,/, '');
    const lowerMime = (mimeType || '').toLowerCase();
    const isWord = lowerMime.includes('wordprocessingml') || lowerMime.includes('msword') || lowerMime.includes('doc');

    if (isWord) {
      try {
        const buffer = Buffer.from(cleanBase64, 'base64');
        const result = await mammoth.extractRawText({ buffer });
        const text = result.value || '';
        if (text.trim().length > 0) {
          return [systemPrompt, `Berikut adalah isi teks dari dokumen Word yang diunggah:\n\n${text}`];
        }
      } catch (e) {
        console.warn('Mammoth extraction failed:', e);
      }
    }

    return [
      systemPrompt,
      {
        inlineData: {
          mimeType: mimeType || 'application/pdf',
          data: cleanBase64,
        },
      },
      'Silakan analisis dokumen di atas dan ekstrak data sesuai instruksi.'
    ];
  }
  return [systemPrompt];
}

function safeJsonParse(text: string): any {
  if (!text) return {};
  try {
    let cleaned = text.trim();
    if (cleaned.startsWith('```')) {
      cleaned = cleaned.replace(/^```[a-z]*\n?/i, '');
      cleaned = cleaned.replace(/```\s*$/, '');
      cleaned = cleaned.trim();
    }
    return JSON.parse(cleaned);
  } catch (e) {
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (inner) {
        // ignore
      }
    }
    throw new Error('Gagal memproses respons AI (format JSON tidak valid dari hasil pindai dokumen).');
  }
}

